/* Public exploration; authenticated party workspaces; sourced campaign records. */
window.createOnboardSystems = function(ctx) {
  'use strict';
  const {D,M,F,state,esc,plain,path,image,pageHead,section,tag,recordingCard,play,toast}=ctx;
  const $=id=>document.getElementById(id), key='shattering-onboard-v1';
  const defaults={version:1,favorites:[],pins:[],notes:'',location:'straleon',board:{selected:[],positions:{},questions:[],theories:[],hiddenEdges:[]},discoveries:{}};
  const array=v=>Array.isArray(v)?v:[];
  let legacy;try{legacy=validate(JSON.parse(localStorage.getItem(key)||'null'));}catch{}
  const restored=validate(window.CampaignSync?.get('onboard',null));let personal=restored||structuredClone(defaults);
  const graph=F.graph, nodes=new Map(graph.nodes.map(n=>[n.id,n]));
  function refreshBoardNodes(){nodes.clear();for(const node of graph.nodes)nodes.set(node.id,node);}
  const initialCards=['person:Rook','person:Lor','person:GHOST-17X','person:L.E.','faction:The Black Sky Imperium (TBS)','person:Yarrow Salt','book:Blue Harvest','person:Killua'].filter(id=>nodes.has(id));
  if(!restored)personal.board.selected=[...initialCards];
  function freshWorkspace(){const fresh=structuredClone(defaults);fresh.board.selected=[...initialCards];return fresh;}
  let boardView={scale:1,session:'all',evidence:null},saveTimer=null,saveQueue=Promise.resolve(),dirty=false,saveBlocked=false,writing=0;
  let confirmations=window.CampaignSync?.get('board-confirmations',{version:1,items:{}})||{version:1,items:{}};
  let knownRemote=JSON.stringify(window.CampaignSync?.get('onboard',null)),knownConfirmations=JSON.stringify(confirmations),knownRole=window.CampaignSync?.role||'public';
  const canEdit=()=>Boolean(window.CampaignSync?.canEdit()),canDM=()=>Boolean(window.CampaignSync?.canDM());
  const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
  const editing=()=>{if(canEdit())return true;toast('Sign in to save changes to the party workspace.');window.CampaignSync?.signIn();return false;};
  let sound={query:'',kind:'all',pack:'all',limit:48,continuous:false}, boardFocus='',journeyIndex=D.SESSIONS.length-1,tourTimer=null,journeyPlaying=false,realmObserver=null;
  const excerpt=(value,max)=>{const text=plain(value);return text.length>max?text.slice(0,max).replace(/\s+\S*$/,'')+'…':text;};
  const time=s=>{s=Math.floor(Number(s)||0);return Math.floor(s/60)+':'+String(s%60).padStart(2,'0');};
  function validBoard(b){
    if(!b||!Array.isArray(b.selected))return null;
    return {selected:b.selected.filter(x=>typeof x==='string').slice(0,30),positions:Object.fromEntries(Object.entries(b.positions||{}).filter(([k,p])=>k!=='__proto__'&&p&&Number.isFinite(p.x)&&Number.isFinite(p.y)).slice(0,60).map(([k,p])=>[k,{x:Math.max(0,Math.min(850,p.x)),y:Math.max(0,Math.min(5000,p.y))}])),questions:array(b.questions).filter(q=>q&&typeof q.id==='string'&&typeof q.text==='string').slice(0,30).map(q=>({id:q.id,text:q.text.slice(0,600)})),theories:array(b.theories).filter(t=>t&&typeof t.a==='string'&&typeof t.b==='string'&&typeof t.label==='string').slice(0,100).map((t,i)=>({id:typeof t.id==='string'?t.id:'legacy-'+i,a:t.a,b:t.b,label:t.label.slice(0,160),status:t.status==='question'?'question':'theory',session:typeof t.session==='string'?t.session.slice(0,24):'',source:typeof t.source==='string'?t.source.slice(0,300):''})),hiddenEdges:array(b.hiddenEdges).filter(x=>typeof x==='string').slice(0,500)};
  }
  function validate(v){
    if(!v||v.version!==1||!Array.isArray(v.favorites)||!Array.isArray(v.pins)||typeof v.notes!=='string'||!validBoard(v.board))return null;
    const board=validBoard(v.board),cases=array(v.investigations?.cases).filter(c=>c&&typeof c.id==='string'&&typeof c.name==='string'&&validBoard(c.board)).slice(0,12).map(c=>({id:c.id,name:c.name.slice(0,80),board:validBoard(c.board)}));
    const active=cases.find(c=>c.id===v.investigations?.active)?.id||cases[0]?.id||'main';
    if(!cases.length)cases.push({id:'main',name:'The main investigation',board});
    const current=cases.find(c=>c.id===active);
    return {version:1,favorites:v.favorites.filter(x=>typeof x==='string').slice(0,3000),pins:v.pins.filter(x=>x&&typeof x.url==='string'&&/^#(world|person|session|ghost|threads)\//.test(x.url)&&typeof x.title==='string').slice(0,12),notes:v.notes.slice(0,30000),location:typeof v.location==='string'?v.location:'straleon',board:current.board,investigations:{active,cases},discoveries:Object.fromEntries(Object.entries(v.discoveries||{}).filter(([k,d])=>k!=='__proto__'&&d&&typeof d.title==='string'&&typeof d.date==='string').slice(0,200))};
  }
  function ensureCases(){if(!personal.investigations)personal.investigations={active:'main',cases:[{id:'main',name:'The main investigation',board:personal.board}]};const active=personal.investigations.cases.find(c=>c.id===personal.investigations.active);if(active)active.board=personal.board;}
  function workspaceMessage(){return saveBlocked?'Changes are unsaved. Export your draft, then reload the shared workspace.':writing?'Saving to the shared workspace…':dirty?'Unsaved changes.':canEdit()?'Shared party workspace.':'Explore freely. Party sign-in is required to save changes.';}
  function saveStatus(){for(const el of document.querySelectorAll('[data-workspace-status],#notesSaved'))el.textContent=workspaceMessage();const notice=$('workspaceRecovery');if(notice)notice.hidden=!saveBlocked;}
  function save(message){
    if(!canEdit())return Promise.resolve(false);
    ensureCases();dirty=true;saveStatus();
    if(saveBlocked){toast('Your draft is still unsaved. Export it before reloading the shared workspace.');return Promise.resolve(false);}
    const snapshot=structuredClone(personal);writing++;saveStatus();
    const operation=saveQueue.then(async()=>{
      try{if(saveBlocked||!canEdit())return false;await window.CampaignSync.save('onboard',snapshot);knownRemote=JSON.stringify(window.CampaignSync.get('onboard',null));if(JSON.stringify(personal)===JSON.stringify(snapshot))dirty=false;if(message)toast(message);return true;}
      catch(error){saveBlocked=true;dirty=true;toast('Not saved: '+(error?.message||'The shared workspace is unavailable.')+' Your draft is still on this page.');return false;}
      finally{writing--;saveStatus();}
    });
    saveQueue=operation.catch(()=>false);return operation;
  }
  function scheduleSave(){dirty=true;clearTimeout(saveTimer);saveStatus();saveTimer=setTimeout(()=>{saveTimer=null;save();},700);}
  function refreshViews(){if(state.route==='ghost')fillSound();if(state.route==='table'){fillTable();if($('tableNotes')&&document.activeElement!==$('tableNotes'))$('tableNotes').value=personal.notes;if($('tableLocation')&&document.activeElement!==$('tableLocation'))$('tableLocation').value=personal.location;}if(state.route==='relationships'){fillBoard();refreshBoardOptions();}if(state.route==='discoveries')ctx.render();saveStatus();}
  function refreshShared(){const sync=window.CampaignSync;if(!sync)return;const current=JSON.stringify(sync.get('onboard',null)),nextRole=sync.role,roleChanged=nextRole!==knownRole,confirmed=sync.get('board-confirmations',{version:1,items:{}})||{version:1,items:{}};if(knownConfirmations!==JSON.stringify(confirmed)){confirmations=confirmed;knownConfirmations=JSON.stringify(confirmed);if(state.route==='relationships')fillBoard();}if(roleChanged){knownRole=nextRole;if(!sync.canEdit()){clearTimeout(saveTimer);saveTimer=null;dirty=false;saveBlocked=false;personal=validate(sync.get('onboard',null))||freshWorkspace();ensureCases();}if(['table','relationships','discoveries'].includes(state.route))ctx.render();}if(current!==knownRemote&&!writing){knownRemote=current;if(!dirty){personal=validate(sync.get('onboard',null))||freshWorkspace();ensureCases();refreshViews();}else{saveBlocked=true;saveStatus();}}}
  function findDiscovery(id,title){if(personal.discoveries[id])return;personal.discoveries[id]={title,date:new Date().toISOString()};if(canEdit())save('Discovery logged · '+title);else toast('Discovered · '+title+' · Sign in to add it to the party collection.');}
  async function pin(title,url,recording){if(!editing())return;if(personal.pins.some(p=>p.url===url)){toast('Already on your table.');return;}if(personal.pins.length>=12){toast('Your table holds twelve records. Remove a pin to make room.');return;}personal.pins.push({title,url,...(recording?{recording}:{})});await save('Pinned to the shared table.');fillTable();}
  ensureCases();
  window.CampaignSync?.subscribe(refreshShared);
  Promise.resolve(window.CampaignSync?.ready).then(refreshShared);
  function marked(text){const terms=sound.query.trim().split(/\s+/).filter(Boolean);if(!terms.length)return esc(text);const re=new RegExp('('+terms.map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')','ig');return String(text).split(re).map((part,i)=>i%2?'<mark>'+esc(part)+'</mark>':esc(part)).join('');}
  function filtered(){const terms=sound.query.toLowerCase().trim().split(/\s+/).filter(Boolean);return M.recordings.filter(r=>(sound.kind==='all'||sound.kind==='favorites'?sound.kind!=='favorites'||personal.favorites.includes(r.id):sound.kind==='shorts'?r.libraryClip:r.kind===sound.kind)&& (sound.pack==='all'||r.category===sound.pack)&&terms.every(t=>[r.title,r.text,r.setting,r.category,r.target].join(' ').toLowerCase().includes(t)));}
  function soundboard(){
    const packs=[...new Set(M.recordings.filter(r=>r.libraryClip).map(r=>r.category))].sort();
    return `<div class="page reveal frequency-page"><section class="frequency-hero"><div class="frequency-grid" aria-hidden="true"></div><div class="frequency-copy"><p class="eyebrow"><span class="status-dot"></span> GHOST-17X / COMMUNICATIONS ARRAY</p><h1>One frequency.<br><em>Zero restraint.</em></h1><p>Recaps, insults, terrible advice, and everything Ghost should have kept to himself.</p><div class="button-row"><button class="button" data-play="s15">▶ Latest transmission</button><a class="button secondary" href="#person/GHOST-17X">Open his dossier ↗</a></div><div class="frequency-readout"><span><b>${M.recordings.length.toLocaleString()}</b> TRANSMISSIONS</span><span><b>28</b> BROOK / SEN-47</span><span><b>17X</b> SIGNAL ONLINE</span></div></div><div class="frequency-portrait">${image(M.matches['GHOST-17X']||'media/art/004-aelyn-and-ghost-hooded-with-rifle-and-drone.webp','GHOST-17X and Aelyn','',true)}<div class="frequency-scan" aria-hidden="true"></div><span>ANGER MANAGEMENT: UNAVAILABLE</span></div></section><div class="frequency-console"><div class="sound-navigation" role="group" aria-label="Transmission type">${[['all','Everything'],['recap','Recaps'],['rant','Rants'],['shorts','Soundboard'],['favorites','★ Favorites']].map(([id,label])=>`<button data-sound-kind="${id}" class="${sound.kind===id?'active':''}" aria-pressed="${sound.kind===id}">${label}</button>`).join('')}</div><div class="sound-controls"><label class="sound-search"><span aria-hidden="true">⌕</span><input id="soundSearch" type="search" placeholder="Find something Ghost said…" aria-label="Search Ghost transcripts" value="${esc(sound.query)}" autocomplete="off"></label><label class="sound-pack"><span>CHANNEL</span><select id="soundPack" aria-label="Filter by sound pack"><option value="all">All channels</option>${packs.map(p=>`<option${p===sound.pack?' selected':''}>${esc(p)}</option>`).join('')}</select></label></div><div class="sound-utility"><span id="soundCount" role="status"></span><label><input id="soundContinuous" type="checkbox"${sound.continuous?' checked':''}> Continuous play</label><button class="text-button" data-sound-random>↝ Random line</button><button class="text-button" data-sound-stop>■ Stop</button></div></div><div class="brook-channel"><div>${image(M.matches.Rook||M.art.find(a=>a.id==='134')?.src,'Rook')}</div><p><span class="eyebrow">NEW CHANNEL / BLACK SKY DEFECTOR</span><strong>Brook. Sen-47. Anything but Rook.</strong><small>28 newly written lines. No disciplinary process survives this frequency.</small></p><button class="button secondary small" data-sound-brook>Open her channel ↗</button></div><div id="soundResults" class="sound-results"></div><div id="soundMore"></div><details class="disclosure transmission-provenance"><summary>Archive & recording notes</summary><p>The soundboard uses campaign-adapted scripts. Ghost’s banter is in character and does not establish campaign facts. Recap narration may be unreliable; each session links to the written record. The original recordings and the Skyrim adaptation audit remain available.</p><div class="button-row"><a class="button secondary small" href="media/soundboard/skyrim-adaptation-audit.csv" download>Download adaptation audit</a><a class="button secondary small" href="media/soundboard/transcripts.json" download>Download transcripts</a><a class="button secondary small" href="ghost-17x/">Original standalone archive ↗</a></div></details></div>`;
  }
  function fillSound(){
    if(!$('soundResults'))return;const list=filtered();state.queue=sound.continuous?list.map(r=>r.id):state.playingId?[state.playingId]:[];
    $('soundCount').textContent=list.length.toLocaleString()+' TRANSMISSIONS'+(sound.query?' FOUND':'');
    $('soundResults').innerHTML=list.slice(0,sound.limit).map(r=>{
      const fav=personal.favorites.includes(r.id),text=r.text||r.setting||'';
      if(!r.libraryClip)return `<section class="transcript-record">${recordingCard(r)}<div class="record-actions"><button data-favorite="${esc(r.id)}" aria-pressed="${fav}" aria-label="${fav?'Remove':'Add'} favorite">${fav?'★':'☆'} Favorite</button><button data-pin-clip="${esc(r.id)}">⌖ Pin to table</button><a href="${esc(r.src)}" download>↓ Audio</a>${r.originalSrc?`<a href="${esc(r.originalSrc)}" download>Original take ↗</a>`:''}</div>${r.chapters?.length?`<details class="transcript-detail"${sound.query?' open':''}><summary>Read & search the transcript · ${r.chapters.length} passages</summary><div class="chapter-list">${r.chapters.map(ch=>`<button data-play="${r.id}" data-seek="${ch.start}" aria-label="Play passage at ${time(ch.start)}"><time>${time(ch.start)}</time><span>${marked(ch.text)}</span><i aria-hidden="true">▶</i></button>`).join('')}</div></details>`:`<details class="transcript-detail"${sound.query?' open':''}><summary>Read transcript</summary><p>${marked(text)}</p></details>`}</section>`;
      return `<article class="sound-card${r.id===state.playingId?' playing':''}" data-recording="${esc(r.id)}"><div class="sound-card-top"><span>${esc(r.category)}</span><button data-favorite="${esc(r.id)}" class="favorite-button${fav?' active':''}" aria-pressed="${fav}" aria-label="${fav?'Remove':'Add'} favorite: ${esc(r.title)}">${fav?'★':'☆'}</button></div><div class="sound-card-body"><button class="sound-play" data-play="${esc(r.id)}" aria-label="Play ${esc(r.title)}">▶</button><p>${marked(text)}</p></div><footer><span>${time(r.duration)} · ${r.index!=null?'#'+String(r.index+1).padStart(4,'0'):'NEW'}</span><div><button data-pin-clip="${esc(r.id)}" aria-label="Pin ${esc(r.title)} to table">⌖</button><button data-copy-line="${esc(r.id)}" aria-label="Copy transcript of ${esc(r.title)}">▤</button><a href="${esc(r.src)}" download aria-label="Download ${esc(r.title)}">↓</a></div></footer></article>`;
    }).join('')||'<div class="empty panel"><h2>Nothing on this frequency.</h2><p>Try a different phrase or channel.</p></div>';
    $('soundMore').innerHTML=list.length>sound.limit?`<button class="button secondary sound-load" data-sound-more>Load 48 more · ${list.length-sound.limit} remaining</button>`:'';
    ctx.syncPlayer?.();
  }
  function queueFor(id){if(!sound.continuous||state.route!=='ghost')state.queue=[id];else state.queue=filtered().map(r=>r.id);}
  function recoveryNotice(){return `<div id="workspaceRecovery" class="workspace-recovery"${saveBlocked?'':' hidden'}><p>These changes have not been saved. Keep an exported copy before loading the current shared workspace.</p><button class="button secondary small" data-export-personal>Export draft ↓</button><button class="button secondary small" data-reload-shared>Reload shared workspace</button></div>`;}
  function caseboard(sub){
    refreshBoardNodes();ensureCases();if(sub&&nodes.has(sub)&&!personal.board.selected.includes(sub)&&personal.board.selected.length<30)personal.board.selected.push(sub);boardFocus=sub;
    const active=personal.investigations.cases.find(c=>c.id===personal.investigations.active);
    return `<div class="page reveal caseboard-page"><div class="case-intro-grid"><div>${pageHead('Investigation / H.O.C.2.A','Pull the thread.','Follow the evidence. Keep the questions worth asking.')}<p class="case-access-note" data-workspace-status role="status">${workspaceMessage()}</p>${!canEdit()?'<button class="button secondary small" data-workspace-signin>Party sign-in ↗</button>':''}<div class="case-index"><label for="boardCase">INVESTIGATION</label><select id="boardCase">${personal.investigations.cases.map(c=>`<option value="${esc(c.id)}"${c.id===active.id?' selected':''}>${esc(c.name)}</option>`).join('')}</select><details class="case-manager"><summary>Manage investigations</summary><form id="caseNameForm"><label>Name<input name="caseName" maxlength="80" value="${esc(active.name)}" required></label><div class="button-row"><button class="button secondary small" name="action" value="rename">Rename</button><button class="button secondary small" name="action" value="new">Create new board</button><button class="text-button" type="button" data-case-delete>Delete this board</button></div><p class="source-note">Up to twelve separate investigations. New boards start empty.</p></form></details></div></div><form id="theoryForm" class="panel case-theory-form"><p class="eyebrow">A working theory</p><h2>Make a connection.</h2><div class="theory-inputs"><label>From<select name="from" aria-label="Theory from">${boardOptions()}</select></label><label>To<select name="to" aria-label="Theory to">${boardOptions('second')}</select></label></div><label>What is the connection?<input name="label" maxlength="160" placeholder="Is this really a coincidence?" required></label><div class="theory-inputs"><label>Stage<select name="status"><option value="question">Question</option><option value="theory" selected>Working theory</option></select></label><label>Supporting session<select name="session"><option value="">Not yet sourced</option>${D.SESSIONS.map(v=>`<option value="${esc(v.num)}">${esc(v.num)} · ${esc(v.title)}</option>`).join('')}</select></label></div><button class="button secondary small" type="submit">Pin the connection</button><p class="source-note">Party theories stay distinct from recorded facts. The DM can confirm a connection with a source.</p></form></div>${recoveryNotice()}<div class="case-toolbar"><label>ADD A RECORD<select id="boardAdd" aria-label="Add a person, faction or place to the board">${addBoardOptions()}</select></label><button class="button secondary small" data-board-question>+ Question note</button><button class="button secondary small" data-board-restore>Restore strings</button><button class="button secondary small" data-export-personal>Export workspace ↓</button></div><div class="case-board-frame"><div class="case-board-top"><div class="case-legend"><span><i></i> Recorded connection</span><span><i></i> Working theory</span><span><i class="confirmed-key"></i> DM confirmed</span><span>Drag a pin to move a card. Drag empty space to pan.</span></div><div class="case-viewport-tools"><label>Evidence from<select id="boardSession" aria-label="Filter connections by source session"><option value="all">Any session / all records</option>${D.SESSIONS.map(v=>`<option value="${esc(v.num)}"${v.num===boardView.session?' selected':''}>${esc(v.num)} · ${esc(v.title)}</option>`).join('')}</select></label><div role="group" aria-label="Board zoom"><button data-board-zoom="out" aria-label="Zoom board out">−</button><output id="boardZoom">100%</output><button data-board-zoom="in" aria-label="Zoom board in">+</button><button data-board-fit>Fit board</button><button data-board-zoom="reset" aria-label="Reset board zoom">1:1</button></div></div></div><div class="caseboard-scroll" id="boardViewport" tabindex="0" aria-label="Investigation board. Drag empty space to pan; use zoom controls or Control and mouse wheel to zoom."><div class="caseboard-scale" id="boardScale"><div class="caseboard" id="caseboard"><div class="caseboard-grain" aria-hidden="true"></div><svg id="caseStrings" viewBox="0 0 1000 680" aria-label="Connections between records"></svg><div id="caseCards"></div></div></div></div><p class="case-board-caption">Select a string to inspect its evidence. Card pins also move with arrow keys; hold Shift for larger steps.</p></div><section class="panel case-evidence-panel"><div class="section-heading"><div><p class="eyebrow">THE EVIDENCE TRAIL</p><h2>What connects them.</h2></div><span id="boardEvidenceCount"></span></div><p id="boardFilterNote" class="source-note"></p><div id="boardEvidence"></div></section><dialog id="boardEvidenceDialog" class="case-evidence-dialog" aria-labelledby="evidenceTitle"><button class="icon-button" data-evidence-close aria-label="Close evidence">×</button><div id="boardEvidenceDetail"></div></dialog></div>`;
  }
  function boardOptions(selected){return personal.board.selected.map(id=>nodes.get(id)).filter(Boolean).map((n,i)=>`<option value="${esc(n.id)}"${selected==='second'&&i===1?' selected':''}>${esc(n.title)}</option>`).join('');}
  function addBoardOptions(){return '<option value="">Choose a person, faction, place…</option>'+graph.nodes.filter(n=>!personal.board.selected.includes(n.id)).sort((a,b)=>a.title.localeCompare(b.title)).map(n=>`<option value="${esc(n.id)}">${esc(n.title)} · ${esc(n.type)}</option>`).join('');}
  function refreshBoardOptions(){if($('boardAdd'))$('boardAdd').innerHTML=addBoardOptions();for(const sel of document.querySelectorAll('#theoryForm select[name="from"],#theoryForm select[name="to"]')){const value=sel.value;sel.innerHTML=boardOptions();if(personal.board.selected.includes(value))sel.value=value;}const cases=$('boardCase');if(cases)cases.innerHTML=personal.investigations.cases.map(c=>`<option value="${esc(c.id)}"${c.id===personal.investigations.active?' selected':''}>${esc(c.name)}</option>`).join('');}
  function boardHeight(){const rows=Math.ceil(personal.board.selected.length/5),notes=Math.ceil(personal.board.questions.length/5),placed=Object.values(personal.board.positions).map(p=>p.y+210);return Math.max(680,rows*220+notes*190+120,...placed);}
  function position(id,i,note=false){return personal.board.positions[id]||{x:55+(i%5)*187,y:note?Math.ceil(personal.board.selected.length/5)*220+60+Math.floor(i/5)*190:60+Math.floor(i/5)*220};}
  function fingerprint(e){return JSON.stringify([e.a,e.b,e.label]);}
  function confirmationKey(e){return personal.investigations.active+':'+e.theoryId;}
  function confirmationFor(e){const entry=confirmations?.items?.[confirmationKey(e)];return entry&&entry.fingerprint===fingerprint(e)?entry:null;}
  function sourceSessions(e){const source=e.personal?(confirmationFor(e)?.session||e.session||''):e.source||'';const match=source.match(/(?:Sessions?\s+|^S)([\d\s,–—\-and]+)/i);if(!match)return [];const fragment=match[1],range=fragment.match(/(\d+)\s*[–—-]\s*(\d+)/);return range?Array.from({length:Math.min(100,Number(range[2])-Number(range[1])+1)},(_,i)=>Number(range[1])+i):(fragment.match(/\d+/g)||[]).map(Number);}
  function sessionMatches(e){if(boardView.session==='all')return true;const nums=boardView.session.match(/\d+/g)?.map(Number)||[];return sourceSessions(e).some(n=>nums.includes(n));}
  function allEdges(){const selected=new Set(personal.board.selected);return [...graph.edges.map((e,i)=>({...e,id:'fact-'+i})),...personal.board.theories.map(e=>({...e,id:'theory-'+e.id,theoryId:e.id,personal:true}))].filter(e=>selected.has(e.a)&&selected.has(e.b)&&!personal.board.hiddenEdges.includes(e.id));}
  function visibleEdges(){return allEdges().filter(sessionMatches);}
  function edgeStatus(e){return !e.personal?'Recorded connection':confirmationFor(e)?'DM confirmed':e.status==='question'?'Open question':'Working theory';}
  function drawStrings(){const svg=$('caseStrings');if(!svg)return;svg.innerHTML=visibleEdges().map(e=>{const a=position(e.a,personal.board.selected.indexOf(e.a)),b=position(e.b,personal.board.selected.indexOf(e.b)),d=`M${a.x+67} ${a.y+10} Q${(a.x+b.x)/2+70} ${(a.y+b.y)/2+50} ${b.x+67} ${b.y+10}`,confirmed=e.personal&&confirmationFor(e);return `<g><path d="${d}" class="${e.personal?'theory-string':'fact-string'}${confirmed?' confirmed-string':''}${e.uncertain||!confirmed&&e.status==='question'?' uncertain':''}"/><path d="${d}" class="string-hit" data-evidence="${esc(e.id)}" tabindex="0" role="button" aria-label="Inspect ${esc(edgeStatus(e))}: ${esc(nodes.get(e.a)?.title)} to ${esc(nodes.get(e.b)?.title)} — ${esc(e.label)}"><title>${esc(e.label)} · ${esc(edgeStatus(e))}</title></path></g>`;}).join('');}
  function applyBoardZoom(anchor){const viewport=$('boardViewport'),board=$('caseboard'),scale=$('boardScale');if(!viewport||!board||!scale)return;const old=Number(board.dataset.zoom)||1,x=anchor?.x??viewport.clientWidth/2,y=anchor?.y??viewport.clientHeight/2,logicalX=(viewport.scrollLeft+x)/old,logicalY=(viewport.scrollTop+y)/old;board.style.transform=`scale(${boardView.scale})`;board.dataset.zoom=boardView.scale;scale.style.width=(1000*boardView.scale)+'px';scale.style.height=(boardHeight()*boardView.scale)+'px';viewport.scrollLeft=logicalX*boardView.scale-x;viewport.scrollTop=logicalY*boardView.scale-y;if($('boardZoom'))$('boardZoom').textContent=Math.round(boardView.scale*100)+'%';}
  function fitBoard(){const v=$('boardViewport');if(!v)return;boardView.scale=Math.max(.18,Math.min(1,(v.clientWidth-12)/1000,(v.clientHeight-12)/boardHeight()));applyBoardZoom();v.scrollLeft=0;v.scrollTop=0;}
  function fillBoard(){if(!$('caseCards'))return;const height=boardHeight();$('caseboard').style.height=height+'px';$('caseStrings').setAttribute('viewBox','0 0 1000 '+height);
    $('caseCards').innerHTML=personal.board.selected.map((id,i)=>{const n=nodes.get(id);if(!n)return '';const p=position(id,i);return `<article class="case-card${id===boardFocus?' in-focus':''}" data-board-card="${esc(id)}" style="left:${p.x}px;top:${p.y}px;--card-tilt:${i%2?-2:2}deg"><button class="case-drag" data-drag-card="${esc(id)}" aria-label="Move ${esc(n.title)} with arrow keys"><i aria-hidden="true"></i>⋮⋮</button><button class="case-remove" data-board-remove="${esc(id)}" aria-label="Remove ${esc(n.title)} from board">×</button><a href="${esc(n.url)}">${n.image?image(n.image,n.title):'<div class="case-symbol">◇</div>'}<strong>${esc(n.title)}</strong><small>${esc(n.type)}</small></a></article>`;}).join('')+personal.board.questions.map((q,i)=>{const p=position(q.id,i,true);return `<article class="case-note" data-board-card="${esc(q.id)}" style="left:${p.x}px;top:${p.y}px"><button class="case-drag" data-drag-card="${esc(q.id)}" aria-label="Move question with arrow keys">⋮⋮</button><button class="case-remove" data-question-remove="${esc(q.id)}" aria-label="Remove question">×</button><label>QUESTION / ${String(i+1).padStart(2,'0')}<textarea data-question-text="${esc(q.id)}" maxlength="600" aria-label="Question ${i+1}"${canEdit()?'':' readonly'}>${esc(q.text)}</textarea></label><button class="case-note-connect" data-question-connect="${esc(q.id)}">Connect this question ↗</button></article>`;}).join('');
    drawStrings();applyBoardZoom();const edges=visibleEdges();$('boardEvidenceCount').textContent=edges.length+' '+(edges.length===1?'connection':'connections');$('boardFilterNote').textContent=boardView.session==='all'?'Sources describe what the campaign record actually says. Questions and theories are party annotations.':'Showing connections explicitly sourced to '+boardView.session+'. Undated dossier links are excluded; this is an evidence filter, not a reconstruction of everything the party knew.';
    $('boardEvidence').innerHTML=edges.length?edges.map(e=>`<article class="evidence-row"><button class="evidence-open" data-evidence="${esc(e.id)}"><span class="evidence-stage ${e.personal?(confirmationFor(e)?'confirmed':'theory'):'recorded'}">${edgeStatus(e)}</span><strong>${esc(nodes.get(e.a)?.title)} ↔ ${esc(nodes.get(e.b)?.title)}</strong><span>${esc(e.label)}</span><small>${esc(e.personal?(confirmationFor(e)?.source||e.session||'Awaiting a source'):e.source+(e.uncertain?' · uncertain':''))} ↗</small></button><button class="evidence-hide" data-edge-hide="${esc(e.id)}" aria-label="Remove this connection from this investigation">×</button></article>`).join(''):'<p class="muted">No connections match this view. Add related records or choose another source session.</p>';saveStatus();}
  function showEvidence(id){const e=allEdges().find(x=>x.id===id);if(!e)return;boardView.evidence=id;const confirmed=confirmationFor(e),sessions=sourceSessions(e),source=confirmed?.source||e.source||'This connection is a party question or theory; it is not a campaign fact.',rec=M.recordings.find(r=>r.kind==='recap'&&sessions.includes(Number(r.session))),matches=D.SESSIONS.filter(s=>{const nums=s.num.match(/\d+/g)?.map(Number)||[];return nums.some(n=>sessions.includes(n));});
    $('boardEvidenceDetail').innerHTML=`<p class="eyebrow">${edgeStatus(e)}</p><h2 id="evidenceTitle">${esc(e.label)}</h2><p class="evidence-people">${esc(nodes.get(e.a)?.title)} <span>↔</span> ${esc(nodes.get(e.b)?.title)}</p><blockquote>${esc(source)}</blockquote>${confirmed?`<p class="source-note">Confirmed by the DM · ${esc(new Date(confirmed.date).toLocaleDateString())}</p>`:''}<div class="evidence-source-links">${matches.map(s=>`<a class="button secondary small" href="${path('session',s.num)}">${esc(s.num)} · Read the written record ↗</a>`).join('')}${rec?`<button class="button secondary small" data-play="${esc(rec.id)}">▶ Full Ghost account</button>`:''}${[e.a,e.b].map(id=>nodes.get(id)).filter(Boolean).map(n=>`<a class="side-link" href="${esc(n.url)}">Open ${esc(n.title)} ↗</a>`).join('')}</div>${e.personal?`<div class="evidence-workflow"><p class="eyebrow">DEVELOP THIS CONNECTION</p>${!confirmed?`<button class="button secondary small" data-theory-stage="${esc(e.theoryId)}">${e.status==='question'?'Develop into a theory':'Return to an open question'}</button>`:''}${canDM()?`<form id="confirmationForm"><input type="hidden" name="theoryId" value="${esc(e.theoryId)}"><label>Confirmed source<input name="source" maxlength="300" placeholder="Which event or record establishes this?" value="${esc(confirmed?.source||'')}" required></label><label>Session<select name="session"><option value="">Other sourced record</option>${D.SESSIONS.map(s=>`<option value="${esc(s.num)}"${(confirmed?.session||e.session)===s.num?' selected':''}>${esc(s.num)} · ${esc(s.title)}</option>`).join('')}</select></label><button class="button secondary small" type="submit">${confirmed?'Update confirmation':'Confirm as DM'}</button>${confirmed?`<button class="text-button" type="button" data-confirmation-remove="${esc(e.theoryId)}">Withdraw confirmation</button>`:''}</form>`:'<p class="source-note">Only the DM can confirm a party connection as established.</p>'}</div>`:''}`;
    const dialog=$('boardEvidenceDialog');if(!dialog.open)dialog.showModal();
  }
  function table(){return `<div class="page reveal table-page">${pageHead('Shared workspace / H.O.C.2.A','At the table.','Keep the current scene, useful faces, and an open frequency within reach.')}${recoveryNotice()}<p class="case-access-note" data-workspace-status role="status">${workspaceMessage()}</p>${legacy?'<button class="text-button legacy-import" data-import-legacy>Import this browser’s previous workspace ↗</button>':''}<div class="table-toolbar"><label>THE CURRENT SCENE<select id="tableLocation" aria-label="Current scene">${[...D.LOCATIONS,D.VOID,...D.PLACE_ENTRIES].map(l=>`<option value="${l.id}"${personal.location===l.id?' selected':''}>${esc(l.name)}</option>`).join('')}</select></label><button class="button secondary small" data-export-personal>Export workspace ↓</button><button class="button secondary small" data-copy-workspace>Copy backup</button><label class="button secondary small import-workspace">Import workspace ↑<input id="importPersonal" type="file" accept="application/json,.json" aria-label="Import your saved workspace"></label></div><div class="table-layout"><div><div id="tableScene"></div><div class="section-heading"><h2>Pinned records</h2><span id="tablePinCount">${personal.pins.length} / 12</span></div><div id="tablePins" class="table-pins"></div></div><aside><section class="panel scratch-panel"><p class="eyebrow">Scratch log</p><label for="tableNotes">Keep a thought before it slips.</label><textarea id="tableNotes" maxlength="30000" placeholder="Names, theories, a suspicious door…"${canEdit()?'':' readonly'}>${esc(personal.notes)}</textarea><span id="notesSaved" class="source-note" role="status">${workspaceMessage()}</span>${!canEdit()?'<button class="text-button" data-workspace-signin>Sign in to add shared notes ↗</button>':''}</section><section class="panel"><p class="eyebrow">Open frequency</p><h3>Party favorites, on tap.</h3><div id="tableFavorites"></div><a class="side-link" href="#ghost">Find more lines ↗</a></section></aside></div></div>`;}
  function fillTable(){if(!$('tableScene'))return;$('tablePinCount').textContent=personal.pins.length+' / 12';const l=[...D.LOCATIONS,D.VOID,...D.PLACE_ENTRIES].find(w=>w.id===personal.location)||D.LOCATIONS[0];$('tableScene').innerHTML=`<a class="table-scene" href="${path('world',l.id)}">${image(l.image,l.name)}<div><p class="eyebrow">CURRENT SCENE</p><h2>${esc(l.name)}</h2><p>${esc(excerpt(l.desc,220))}</p><span>Open the dossier ↗</span></div></a>`;
    $('tablePins').innerHTML=personal.pins.length?personal.pins.map((p,i)=>`<article class="table-pin"><div><p class="eyebrow">PINNED / ${String(i+1).padStart(2,'0')}</p><a href="${esc(p.url)}"><h3>${esc(p.title)}</h3></a>${p.recording?`<button class="button secondary small" data-play="${esc(p.recording)}">▶ Play line</button>`:''}</div><button class="icon-button" data-pin-remove="${i}" aria-label="Unpin ${esc(p.title)}">×</button></article>`).join(''):'<div class="notice">Open a world, person, session, thread, or Ghost line and choose “Pin to table.”</div>';
    $('tableFavorites').innerHTML=personal.favorites.slice(0,8).map(id=>M.recordings.find(r=>r.id===id)).filter(Boolean).map(r=>`<button class="table-line" data-play="${esc(r.id)}"><span>▶</span><strong>${esc(r.title)}</strong></button>`).join('')||'<p class="muted">Star a line in the Ghost archive to bring it here.</p>';}
  function journey(){return `<div class="journey-page"><section class="journey-shell"><div class="map-stage journey-map" id="journeyMap"><canvas aria-label="The crew’s journey through the galaxy"></canvas><div class="map-nodes"></div></div><div class="journey-shade" aria-hidden="true"></div><div class="journey-heading"><p class="eyebrow">H.O.C.2.A / OUR FLIGHT PATH</p><h1>We were here.</h1></div><article id="journeyStory" class="journey-story"></article><div class="journey-controls"><button class="icon-button" data-journey-step="-1" aria-label="Previous journey stop">‹</button><button class="button secondary small" data-journey-toggle>▶ Start tour</button><button class="icon-button" data-journey-step="1" aria-label="Next journey stop">›</button><label><input id="journeyCommentary" type="checkbox"> Ghost commentary</label><select id="journeyStop" aria-label="Jump to a journey stop">${D.SESSIONS.map((s,i)=>`<option value="${i}"${i===journeyIndex?' selected':''}>${s.num} · ${esc(s.title)}</option>`).join('')}</select></div><div class="journey-progress" id="journeyProgress"></div></section></div>`;}
  function stopTour(){journeyPlaying=false;clearTimeout(tourTimer);tourTimer=null;const b=document.querySelector('[data-journey-toggle]');if(b)b.textContent='▶ Start tour';}
  function showJourney(){const s=D.SESSIONS[journeyIndex],realm=['S11','S12'].includes(s.num),id=realm?'celestial-tunnel':s.where?.id,l=[...D.LOCATIONS,D.VOID,...D.PLACE_ENTRIES].find(w=>w.id===id),num=Number(s.num.slice(1)),rec=M.recordings.find(r=>r.kind==='recap'&&r.session===num)||M.recordings.find(r=>r.session===num&&!r.libraryClip);const storyArt={S0:'007',S2:'027',S3:'020',S4:'021',S5:'035',S6:'061',S7:'064',S8:'072','S9–10':'081',S11:'102',S12:'096',S13:'080',S14:'126',S15:'130'},art=s.image||M.art.find(a=>a.id===storyArt[s.num]&&!a.video&&!a.source.includes('_alts'))?.src||l?.image,date=s.date||M.recaps.find(r=>r.session===num)?.date||rec?.date||'';
    $('journeyStory').innerHTML=`${image(art,s.title,'journey-art')}<div class="journey-story-copy"><p class="eyebrow">STOP ${String(journeyIndex+1).padStart(2,'0')} / ${D.SESSIONS.length} · ${esc(s.num)}${date?' · '+esc(date):''}</p><h2>${esc(s.title)}</h2><p class="journey-place">${esc(l?.name||s.where?.label||'In transit')}</p><p>${esc(excerpt(s.summary,410))}</p><div class="button-row"><a class="button secondary small" href="${path('session',s.num)}">Read the flight log ↗</a>${l?`<a class="button secondary small" href="${path('world',l.id)}">Explore this place ↗</a>`:''}${rec?`<button class="button secondary small" data-play="${rec.id}">▶ Ghost’s commentary</button>`:''}</div></div>`;
    $('journeyStop').value=journeyIndex;$('journeyProgress').innerHTML=D.SESSIONS.map((r,i)=>`<button data-journey-jump="${i}" class="${i===journeyIndex?'active':''}" aria-label="Journey stop ${esc(r.num)}" aria-current="${i===journeyIndex?'step':'false'}"></button>`).join('');
    const g=state.galaxy;g?.setSession(journeyIndex);if(realm){if(g){g.zoom=.34;g.pan={x:0,y:0};g.target={x:0,y:0};g.labelKey=null;g.draw();}}else if(l){const parent=l.parent||l.id;g?.focus(parent);}if($('journeyCommentary')?.checked&&rec)play(rec.id,0);
    if(journeyPlaying){clearTimeout(tourTimer);tourTimer=setTimeout(()=>{if(journeyIndex>=D.SESSIONS.length-1){stopTour();return;}journeyIndex++;showJourney();},$('journeyCommentary')?.checked&&rec?Math.max(15000,(rec.duration||0)*1000+1500):15000);}}
  function discoveries(){const items=Object.values(personal.discoveries).sort((a,b)=>a.date.localeCompare(b.date));return `<div class="page reveal discoveries-page">${pageHead('The things you noticed','A few little discoveries.','Somebody has been leaving things around the galaxy. A shared record of what the party has found.')}<section class="discovery-hero"><span class="discovery-orbit" aria-hidden="true">✧</span><div><p class="eyebrow">PARTY COLLECTION</p><h2>${items.length} ${items.length===1?'discovery':'discoveries'} logged.</h2><p>No coordinates. No spoilers. Keep exploring.</p></div><button class="button secondary small" data-export-personal>Export collection ↓</button></section><div class="discovery-grid">${items.map((d,i)=>`<article class="discovery-card"><span class="discovery-stamp">${String(i+1).padStart(2,'0')}</span><p class="eyebrow">FOUND / ${esc(new Date(d.date).toLocaleDateString())}</p><h3>${esc(d.title)}</h3><span class="discovery-star" aria-hidden="true">✧</span></article>`).join('')}<article class="discovery-card undiscovered"><span aria-hidden="true">?</span><p>Something else is out there.</p></article></div></div>`;}
  function decorate(route,sub){
    const main=$('main');if(['world','person','session','threads'].includes(route)&&sub){const title=main.querySelector('h1')?.textContent||sub;const anchor=main.querySelector('.breadcrumb')||main.querySelector('.page-head');anchor?.insertAdjacentHTML('afterend',`<div class="dossier-actions"><button class="text-button" data-pin-record data-pin-title="${esc(title)}" data-pin-url="${esc(path(route,sub))}">⌖ Pin to table</button></div>`);}
    if(route==='world'){
      const w=[...D.LOCATIONS,D.VOID,...D.PLACE_ENTRIES].find(l=>l.id===sub);if(!w)return;const text=plain([w.name,w.desc,...(w.factions||[])].join(' '));main.classList.toggle('dossier-celestial',sub==='celestial-tunnel');main.classList.toggle('dossier-military',/Black Sky|Noctara|Sen-47/i.test(text));
      const ancestors=[];let p=w,seen=new Set();while(p?.parent&&!seen.has(p.id)){seen.add(p.id);p=D.PLACE_ENTRIES.find(l=>l.id===p.parent)||D.LOCATIONS.find(l=>l.id===p.parent);if(p)ancestors.unshift(p);}
      const crumb=main.querySelector('.breadcrumb');if(crumb&&ancestors.length)crumb.innerHTML=`<a href="#map">Star map</a><span>/</span>${ancestors.map(p=>`<a href="${path('world',p.id)}">${esc(p.name)}</a><span>/</span>`).join('')}<span>${esc(w.name)}</span>`;
      const root=ancestors[0]||w,descendants=[];function walk(id,depth,visited=new Set()){if(visited.has(id))return;visited.add(id);for(const c of D.PLACE_ENTRIES.filter(l=>l.parent===id)){descendants.push({c,depth});walk(c.id,depth+1,visited);}}walk(root.id,0);
      if(descendants.length)main.querySelector('.dossier-side')?.insertAdjacentHTML('beforeend',`<section class="panel place-tree"><p class="eyebrow">EXPLORE / ${esc(root.name)}</p><a class="${root.id===sub?'active':''}" href="${path('world',root.id)}">${esc(root.name)}</a>${descendants.map(({c,depth})=>`<a style="--depth:${depth+1}" class="${c.id===sub?'active':''}" href="${path('world',c.id)}">${esc(c.name)}</a>`).join('')}</section>`);
    }
    if(route==='person'&&['Rook','GHOST-17X','L.E.'].includes(sub))main.classList.add(sub==='L.E.'?'dossier-celestial':'dossier-military');
    if(route==='lore'&&sub==='factions')main.querySelectorAll('.panel,.faction-card').forEach(el=>{if(/Black Sky Imperium/.test(el.querySelector('h2,h3')?.textContent||''))el.classList.add('military-panel');});
  }
  function mount(route,sub){decorate(route,sub);if(route==='ghost'){if(sub){const r=M.recordings.find(r=>r.id===sub);if(r){sound.query=r.title;sound.pack='all';sound.kind='all';$('soundSearch').value=sound.query;}}fillSound();}if(route==='relationships'){refreshBoardNodes();fillBoard();refreshBoardOptions();}if(route==='table')fillTable();if(route==='journey'){state.galaxy=new window.ShatteringGalaxy($('journeyMap'),{locations:[...D.LOCATIONS,D.VOID],sessions:D.SESSIONS,motion:state.motion,onSelect:()=>{}});showJourney();}const stage=$('mapStage');if(stage){realmObserver=new MutationObserver(()=>{if(stage.dataset.constellationComplete==='true')findDiscovery('celestial-chart','Celestial cartographer');});realmObserver.observe(stage,{attributes:true,attributeFilter:['data-constellation-complete']});}}
  function unmount(){stopTour();realmObserver?.disconnect();realmObserver=null;if(saveTimer){clearTimeout(saveTimer);saveTimer=null;save();}}
  window.addEventListener('beforeunload',e=>{if(dirty&&canEdit()){e.preventDefault();e.returnValue='';}});
  function exportPersonal(){ensureCases();const blob=new Blob([JSON.stringify(personal,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='shattering-workspace-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
  async function reloadShared(){clearTimeout(saveTimer);saveTimer=null;if(dirty&&!window.confirm('Reload the shared workspace and discard the unsaved draft on this page? Export a copy first if you want to keep it.'))return;try{await saveQueue;await window.CampaignSync?.refresh?.();personal=validate(window.CampaignSync?.get('onboard',null))||freshWorkspace();ensureCases();dirty=false;saveBlocked=false;knownRemote=JSON.stringify(window.CampaignSync?.get('onboard',null));ctx.render();toast('Shared workspace loaded.');}catch(error){toast('Could not reload: '+(error?.message||'Connection unavailable.'));}}
  let confirming=false;
  async function writeConfirmation(theoryId,entry){if(!canDM()){toast('DM access is required to confirm evidence.');return false;}if(confirming)return false;const theory=personal.board.theories.find(t=>t.id===theoryId);if(!theory)return false;const candidate=structuredClone(confirmations),key=personal.investigations.active+':'+theoryId;candidate.version=1;candidate.items=candidate.items||{};if(entry)candidate.items[key]={...entry,fingerprint:fingerprint(theory),date:new Date().toISOString()};else delete candidate.items[key];confirming=true;try{await window.CampaignSync.save('board-confirmations',candidate);confirmations=window.CampaignSync.get('board-confirmations',candidate);knownConfirmations=JSON.stringify(confirmations);fillBoard();showEvidence('theory-'+theoryId);toast(entry?'DM confirmation saved.':'Confirmation withdrawn.');return true;}catch(error){toast('Confirmation was not saved: '+(error?.message||'Please try again.'));return false;}finally{confirming=false;}}
  document.addEventListener('click',async e=>{
    const evidence=e.target.closest('[data-evidence]');if(evidence){showEvidence(evidence.dataset.evidence);return;}
    const b=e.target.closest('button,a');if(!b)return;
    if(b.hasAttribute('data-workspace-signin'))window.CampaignSync?.signIn();
    if(b.hasAttribute('data-reload-shared'))await reloadShared();
    if(b.hasAttribute('data-evidence-close'))$('boardEvidenceDialog')?.close();
    if(b.closest('#boardEvidenceDialog')&&b.tagName==='A')$('boardEvidenceDialog')?.close();
    if(b.hasAttribute('data-import-legacy')){if(!editing())return;if(legacy&&window.confirm('Replace the shared party workspace with this browser’s previous notes, pins, favorites and board? Export the shared workspace first if you need a backup.')){personal=structuredClone(legacy);ensureCases();if(await save('Previous device workspace imported.'))ctx.render();}return;}
    if(b.hasAttribute('data-book')){const where=state.route+(state.sub?'/'+state.sub:'');findDiscovery('paperback-'+where,'A borrowed edition · '+($('viewLabel')?.textContent||'The archive'));}
    if(b.dataset.favorite){if(!editing())return;const id=b.dataset.favorite,i=personal.favorites.indexOf(id);if(i<0)personal.favorites.push(id);else personal.favorites.splice(i,1);save();fillSound();}
    if(b.dataset.pinClip){const r=M.recordings.find(r=>r.id===b.dataset.pinClip);if(r)pin(r.title,path('ghost',r.id),r.id);}
    if(b.hasAttribute('data-pin-record'))pin(b.dataset.pinTitle,b.dataset.pinUrl);
    if(b.dataset.pinRemove!==undefined){if(!editing())return;personal.pins.splice(Number(b.dataset.pinRemove),1);save();fillTable();}
    if(b.hasAttribute('data-export-personal'))exportPersonal();
    if(b.hasAttribute('data-copy-workspace'))navigator.clipboard.writeText(JSON.stringify(personal,null,2)).then(()=>toast('Workspace backup copied.')).catch(()=>toast('Use Export workspace to save your backup.'));
    if(b.dataset.copyLine){const r=M.recordings.find(r=>r.id===b.dataset.copyLine);if(r)navigator.clipboard.writeText(r.text||r.title).then(()=>toast('Transcript copied.')).catch(()=>toast('Select the transcript text to copy it.'));}
    if(b.dataset.soundKind){sound.kind=b.dataset.soundKind;sound.limit=48;document.querySelectorAll('[data-sound-kind]').forEach(el=>{el.classList.toggle('active',el.dataset.soundKind===sound.kind);el.setAttribute('aria-pressed',String(el.dataset.soundKind===sound.kind));});fillSound();}
    if(b.hasAttribute('data-sound-brook')){sound.kind='shorts';sound.pack='Brook / Sen-47';sound.query='';sound.limit=48;$('soundPack').value=sound.pack;$('soundSearch').value='';document.querySelectorAll('[data-sound-kind]').forEach(el=>{el.classList.toggle('active',el.dataset.soundKind===sound.kind);el.setAttribute('aria-pressed',String(el.dataset.soundKind===sound.kind));});fillSound();$('soundResults').scrollIntoView({block:'start',behavior:state.motion?'smooth':'instant'});}
    if(b.hasAttribute('data-sound-more')){sound.limit+=48;fillSound();}
    if(b.hasAttribute('data-sound-stop')){$('ghostAudio').pause();$('ghostAudio').currentTime=0;}
    if(b.hasAttribute('data-sound-random')){const list=filtered().filter(r=>r.libraryClip);if(list.length)play(list[Math.floor(Math.random()*list.length)].id,0);else toast('No short lines in this channel.');}
    if(b.dataset.boardRemove){if(!editing())return;personal.board.selected=personal.board.selected.filter(id=>id!==b.dataset.boardRemove);delete personal.board.positions[b.dataset.boardRemove];save();fillBoard();refreshBoardOptions();}
    if(b.hasAttribute('data-board-question')){if(!editing())return;if(personal.board.questions.length>=30){toast('Thirty questions is plenty for one board.');return;}personal.board.questions.push({id:'question-'+uid(),text:''});save();fillBoard();document.querySelector('.case-note:last-child textarea')?.focus();}
    if(b.dataset.questionRemove){if(!editing())return;personal.board.questions=personal.board.questions.filter(q=>q.id!==b.dataset.questionRemove);delete personal.board.positions[b.dataset.questionRemove];save();fillBoard();}
    if(b.dataset.questionConnect){const q=personal.board.questions.find(q=>q.id===b.dataset.questionConnect);if(q){const form=$('theoryForm');form.elements.label.value=q.text.slice(0,160);form.elements.status.value='question';form.scrollIntoView({block:'center',behavior:state.motion?'smooth':'instant'});form.elements.from.focus();}}
    if(b.hasAttribute('data-board-restore')){if(!editing())return;personal.board.hiddenEdges=[];save('The board’s strings are restored.');fillBoard();}
    if(b.dataset.edgeHide){if(!editing())return;const edge=allEdges().find(v=>v.id===b.dataset.edgeHide);if(edge?.personal)personal.board.theories=personal.board.theories.filter(t=>t.id!==edge.theoryId);else personal.board.hiddenEdges.push(b.dataset.edgeHide);save();fillBoard();}
    if(b.dataset.theoryStage){if(!editing())return;const theory=personal.board.theories.find(t=>t.id===b.dataset.theoryStage);if(theory){theory.status=theory.status==='question'?'theory':'question';await save('Connection stage updated.');fillBoard();showEvidence('theory-'+theory.id);}}
    if(b.dataset.confirmationRemove)await writeConfirmation(b.dataset.confirmationRemove,null);
    if(b.hasAttribute('data-board-fit'))fitBoard();
    if(b.dataset.boardZoom){boardView.scale=b.dataset.boardZoom==='reset'?1:Math.max(.18,Math.min(1.6,boardView.scale*(b.dataset.boardZoom==='in'?1.2:1/1.2)));applyBoardZoom();}
    if(b.hasAttribute('data-case-delete')){if(!editing())return;const group=personal.investigations;if(group.cases.length===1){toast('Keep at least one investigation. Create another before deleting this one.');return;}const current=group.cases.find(c=>c.id===group.active);if(window.confirm('Delete “'+current.name+'” from the shared workspace?')){group.cases=group.cases.filter(c=>c.id!==group.active);group.active=group.cases[0].id;personal.board=group.cases[0].board;save('Investigation deleted.');ctx.render();}}
    if(b.dataset.journeyStep){stopTour();journeyIndex=(journeyIndex+Number(b.dataset.journeyStep)+D.SESSIONS.length)%D.SESSIONS.length;showJourney();}
    if(b.dataset.journeyJump!==undefined){stopTour();journeyIndex=Number(b.dataset.journeyJump);showJourney();}
    if(b.hasAttribute('data-journey-toggle')){if(journeyPlaying)stopTour();else{if(journeyIndex===D.SESSIONS.length-1)journeyIndex=0;journeyPlaying=true;b.textContent='Ⅱ Pause tour';showJourney();}}
  });
  document.addEventListener('input',e=>{const t=e.target;if(t.id==='soundSearch'){sound.query=t.value;sound.limit=48;fillSound();}if(t.id==='tableNotes'){if(!canEdit()){t.value=personal.notes;return;}personal.notes=t.value;scheduleSave();}if(t.dataset.questionText){if(!canEdit())return;const q=personal.board.questions.find(q=>q.id===t.dataset.questionText);if(q){q.text=t.value;scheduleSave();}}});
  document.addEventListener('change',async e=>{const t=e.target;
    if(t.id==='soundPack'){sound.pack=t.value;sound.limit=48;fillSound();}if(t.id==='soundContinuous'){sound.continuous=t.checked;fillSound();}
    if(t.id==='boardSession'){boardView.session=t.value;fillBoard();}
    if(t.id==='boardCase'){ensureCases();const next=personal.investigations.cases.find(c=>c.id===t.value);if(next){personal.investigations.active=next.id;personal.board=next.board;boardView.session='all';if(canEdit())save();ctx.render();}}
    if(t.id==='boardAdd'&&t.value){if(!editing()){t.value='';return;}if(personal.board.selected.length>=30){toast('Your board holds thirty records.');return;}personal.board.selected.push(t.value);save();fillBoard();refreshBoardOptions();}
    if(t.id==='tableLocation'){if(!editing()){t.value=personal.location;return;}personal.location=t.value;save();fillTable();}
    if(t.id==='journeyCommentary'){if(t.checked)showJourney();else if(state.playingId&&M.recordings.find(r=>r.id===state.playingId)?.session===Number(D.SESSIONS[journeyIndex].num.slice(1)))$('ghostAudio').pause();}
    if(t.id==='journeyStop'){stopTour();journeyIndex=Number(t.value);showJourney();}
    if(t.id==='importPersonal'&&t.files[0]){if(!editing()){t.value='';return;}try{if(t.files[0].size>1000000)throw Error();const v=validate(JSON.parse(await t.files[0].text()));if(!v)throw Error();if(!window.confirm('Replace the shared workspace with this imported file? Export the current version first if you need a backup.'))return;personal=v;ensureCases();await save('Shared workspace imported.');ctx.render();}catch{toast('That file is not a valid Shattering workspace.');}}
  });
  document.addEventListener('submit',async e=>{
    const form=e.target;if(!['theoryForm','caseNameForm','confirmationForm'].includes(form.id))return;e.preventDefault();if(!editing())return;const f=new FormData(form);
    if(form.id==='theoryForm'){const a=f.get('from'),b=f.get('to'),label=String(f.get('label')).trim();if(a===b||!nodes.has(a)||!nodes.has(b)||!label){toast('Choose two different records and name their connection.');return;}if(personal.board.theories.length>=100){toast('This investigation holds one hundred connections. Start another board to keep exploring.');return;}personal.board.theories.push({id:uid(),a,b,label,status:f.get('status')==='question'?'question':'theory',session:String(f.get('session')||''),source:''});if(await save('Connection pinned to the investigation.'))form.elements.label.value='';fillBoard();}
    if(form.id==='caseNameForm'){const name=String(f.get('caseName')||'').trim(),group=personal.investigations;if(!name)return;if(e.submitter?.value==='new'){if(group.cases.length>=12){toast('The party can keep twelve investigations. Export one before removing it to make room.');return;}ensureCases();const board=structuredClone(defaults.board),id='case-'+uid();group.cases.push({id,name,board});group.active=id;personal.board=board;}else group.cases.find(c=>c.id===group.active).name=name;await save('Investigation saved.');ctx.render();}
    if(form.id==='confirmationForm')await writeConfirmation(String(f.get('theoryId')),{source:String(f.get('source')||'').trim().slice(0,300),session:String(f.get('session')||'')});
  });
  let drag=null,pan=null;
  document.addEventListener('pointerdown',e=>{const h=e.target.closest('[data-drag-card]');if(h){e.preventDefault();const id=h.dataset.dragCard,card=h.closest('[data-board-card]'),i=id.startsWith('question-')?personal.board.questions.findIndex(q=>q.id===id):personal.board.selected.indexOf(id),p=position(id,i,id.startsWith('question-'));drag={id,card,h,x:e.clientX,y:e.clientY,p};h.setPointerCapture(e.pointerId);return;}const v=e.target.closest('#boardViewport');if(v&&!e.target.closest('button,a,input,textarea,select,[data-evidence],[data-board-card]')){e.preventDefault();pan={v,x:e.clientX,y:e.clientY,left:v.scrollLeft,top:v.scrollTop};v.classList.add('panning');v.setPointerCapture(e.pointerId);}});
  document.addEventListener('pointermove',e=>{if(pan){pan.v.scrollLeft=pan.left-(e.clientX-pan.x);pan.v.scrollTop=pan.top-(e.clientY-pan.y);}if(!drag)return;const p={x:Math.max(0,Math.min(850,drag.p.x+(e.clientX-drag.x)/boardView.scale)),y:Math.max(0,Math.min(boardHeight()-210,drag.p.y+(e.clientY-drag.y)/boardView.scale))};personal.board.positions[drag.id]=p;drag.card.style.left=p.x+'px';drag.card.style.top=p.y+'px';drawStrings();});
  const finishDrag=()=>{if(drag){if(canEdit())save();drag=null;}if(pan){pan.v.classList.remove('panning');pan=null;}};document.addEventListener('pointerup',finishDrag);document.addEventListener('pointercancel',finishDrag);
  document.addEventListener('wheel',e=>{const v=e.target.closest('#boardViewport');if(!v||(!e.ctrlKey&&!e.metaKey))return;e.preventDefault();const r=v.getBoundingClientRect();boardView.scale=Math.max(.18,Math.min(1.6,boardView.scale*Math.exp(-e.deltaY*.002)));applyBoardZoom({x:e.clientX-r.left,y:e.clientY-r.top});},{passive:false});
  document.addEventListener('keydown',e=>{const edge=e.target.closest('[data-evidence]');if(edge&&['Enter',' '].includes(e.key)){e.preventDefault();showEvidence(edge.dataset.evidence);return;}const h=e.target.closest('[data-drag-card]');if(!h||!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const id=h.dataset.dragCard,i=id.startsWith('question-')?personal.board.questions.findIndex(q=>q.id===id):personal.board.selected.indexOf(id),p=position(id,i,id.startsWith('question-')),step=e.shiftKey?30:10;personal.board.positions[id]={x:Math.max(0,Math.min(850,p.x+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0))),y:Math.max(0,Math.min(boardHeight()-210,p.y+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0)))};const card=h.closest('[data-board-card]'),pos=personal.board.positions[id];card.style.left=pos.x+'px';card.style.top=pos.y+'px';drawStrings();if(canEdit())scheduleSave();});
  return {soundboard,caseboard,table,journey,discoveries,mount,unmount,queueFor,fillSound};
};
